TRUNCATE TABLE order_status_history;

INSERT INTO order_status_history (order_id, status, createdAt) 
SELECT id, 'Pending', createdAt FROM orders;

INSERT INTO order_status_history (order_id, status, createdAt) 
SELECT id, 'Ready', ready_at FROM orders 
WHERE ready_at IS NOT NULL;

INSERT INTO order_status_history (order_id, status, createdAt) 
SELECT id, 'On the Way', picked_up_at FROM orders 
WHERE picked_up_at IS NOT NULL;

INSERT INTO order_status_history (order_id, status, createdAt) 
SELECT id, 'Delivered', delivered_at FROM orders 
WHERE delivered_at IS NOT NULL AND status = 'Delivered';

